import java.io.File;
import java.nio.file.Path;

public class BadFileAccess {
    // This method is vulnerable because it allows the user to provide arbitrary file paths
    // without validation, leading to potential path traversal or sensitive file access.
    public void readFile(String fileName) {
        // Constructing a File object directly from user input
        File file = new File("/var/data/" + fileName); 
        // Vulnerable: If fileName is "../config.properties", it reads outside the intended directory
        // and exposes sensitive configuration data.
        System.out.println("Reading: " + file.getAbsolutePath());
    }
}
