import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class GoodFileAccess {

    public void readFile(String fileName) {
        // Define the base directory that should be strictly adhered to
        String baseDir = "/var/data/";

        // Construct the path using Path of Java NIO to ensure it is normalized
        Path basePath = Paths.get(baseDir).toAbsolutePath().normalize();
        Path userPath = basePath.resolve(fileName).normalize();

        // Ensure the resolved path is still within the allowed base directory
        // This prevents path traversal attacks like ../../etc/passwd
        if (!userPath.startsWith(basePath)) {
            throw new SecurityException("Attempted to access file outside allowed directory");
        }

        File file = userPath.toFile();
        if (file.exists() && file.isFile()) {
            System.out.println("Reading safely from: " + file.getAbsolutePath());
        }
    }
}
